import React, { useState } from "react";
import api from "@landinghub/api";
import Background from "../components/Background";
import { CheckCircle2, ChevronDown } from "lucide-react";
import "../styles/Support.css";

const faqsData = [
  { question: "Làm sao để tạo landing page nhanh chóng?", answer: "Chọn template, kéo thả các thành phần và xuất bản. Không cần kỹ năng code." },
  { question: "Có thể tùy chỉnh layout không?", answer: "LandingHub cho phép chỉnh sửa mọi phần tử, màu sắc, font chữ và bố cục." },
  { question: "Hỗ trợ kỹ thuật như thế nào?", answer: "Chúng tôi có chat trực tuyến và form liên hệ 24/7, đảm bảo phản hồi nhanh chóng." }
];

const Support = () => {
  const [openIndex, setOpenIndex] = useState(null);
  const [form, setForm] = useState({ name: "", email: "", phone: "", notes: "" });
  const [submitted, setSubmitted] = useState(false);

  const toggleFAQ = (index) => setOpenIndex(openIndex === index ? null : index);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email) {
      alert("Tên và Email là bắt buộc!");
      return;
    }
    try {
      await api.post("/api/leads", { ...form, status: "new" });
      setSubmitted(true);
      setForm({ name: "", email: "", phone: "", notes: "" });
      setTimeout(() => setSubmitted(false), 4000);
    } catch (err) {
      console.error(err);
      alert("Gửi thông tin thất bại. Vui lòng thử lại.");
    }
  };

  return (
    <Background showShapes={false} fullWidth>
      <div className="support-container">
        {/* Hero Section */}
        <section className="support-hero">
          <div className="hero-inner">
            <h1>Trung tâm Hỗ trợ LandingHub</h1>
            <p>
              Giúp bạn giải quyết vấn đề, khám phá tính năng và nhận được phản hồi nhanh chóng.
            </p>
          </div>
        </section>

        {/* FAQ */}
        <section className="faq-section">
          <h2>Câu hỏi thường gặp</h2>
          <div className="faq-list">
            {faqsData.map((faq, idx) => (
              <div
                key={idx}
                className={`faq-item ${openIndex === idx ? "open" : ""}`}
                onClick={() => toggleFAQ(idx)}
              >
                <div className="faq-header">
                  <span>{faq.question}</span>
                  <ChevronDown className={`faq-icon ${openIndex === idx ? "rotate" : ""}`} size={18} />
                </div>
                <div className="faq-body">{faq.answer}</div>
              </div>
            ))}
          </div>
        </section>

        {/* Contact Form */}
        <section className="contact-section">
          <div className="contact-card">
            <h2>Liên hệ với đội ngũ hỗ trợ</h2>
            <p>Điền thông tin của bạn và chúng tôi sẽ phản hồi sớm nhất có thể.</p>

            {submitted && (
              <div className="success-message">
                <CheckCircle2 size={24} /> Cảm ơn bạn! Thông tin đã được gửi thành công.
              </div>
            )}

            <form onSubmit={handleSubmit} className="contact-form">
              <input
                name="name"
                value={form.name}
                onChange={handleChange}
                placeholder="Họ và tên *"
                required
              />
              <input
                name="email"
                type="email"
                value={form.email}
                onChange={handleChange}
                placeholder="Email *"
                required
              />
              <input
                name="phone"
                value={form.phone}
                onChange={handleChange}
                placeholder="Số điện thoại"
              />
              <textarea
                name="notes"
                value={form.notes}
                onChange={handleChange}
                placeholder="Nội dung cần hỗ trợ"
                rows={4}
              />
              <button type="submit" className="btn-submit">
                Gửi yêu cầu
              </button>
            </form>
          </div>
        </section>

        {/* CTA */}
        <section className="cta-support">
          <div className="cta-inner">
            <h2>Luôn đồng hành cùng bạn</h2>
            <p>Đội ngũ LandingHub luôn sẵn sàng hỗ trợ 24/7 cho mọi khách hàng.</p>
            <button className="cta-btn">Trò chuyện ngay</button>
          </div>
        </section>
      </div>
    </Background>
  );
};

export default Support;
